    sudoku_rules_end_title: "完成一局",
    sudoku_term_win: "已解出",
    sudoku_rules_win: "当整个网格被完全填满且不存在任何冲突时，这道题即被解出。",
    sudoku_term_difficulty: "难度",
    sudoku_rules_difficulty: "简单、中等和困难三种难度的唯一区别在于 81 个格子中起始就填好的数字有多少——提示数越少，需要推理的步骤就越多。",
    pegsolitaire_new_game: "新局",
