    pegsolitaire_rules_basics_title: "基本玩法",
    pegsolitaire_term_board: "棋盘与起始位置",
    pegsolitaire_rules_board: "经典的英式棋盘由 33 个孔组成，呈十字形排列。除正中央的孔起始为空外，其余每个孔都放有一枚棋钉。",
    pegsolitaire_term_jump: "跳子",
    pegsolitaire_rules_jump: "选中一枚棋钉，然后选择沿直线（上、下、左或右，绝不能斜跳）方向、间隔两格的一个空孔，且中间那一格必须恰好有另一枚棋钉。该棋钉会跳入空孔，被跳过的那枚棋钉则从棋盘上移除。",
