    mastermind_rules_title: "Mastermind 规则",
    mastermind_rules_intro: "关于 PaperGames 中 Mastermind 玩法的简明说明——无论你是生疏了还是刚开始学，都能派上用场。",
    mastermind_rules_basics_title: "基本玩法",
    mastermind_term_code: "秘密代码",
    mastermind_rules_code: "每局新游戏开始时，电脑会选定一个由四个位置组成的隐藏代码，每个位置是圆形、方形、三角形、菱形、星形或十字形这六种图形之一。根据难度不同，同一个图形在代码中可能出现不止一次。",
    mastermind_term_guess: "进行猜测",
    mastermind_rules_guess: "点击一个格子即可在六种图形之间循环切换，等四个格子都显示出你想尝试的图形后，点击“提交猜测”。无论秘密代码本身是否有重复图形，你在猜测中都可以自由重复使用某个图形。",
    mastermind_term_feedback: "解读提示",
    mastermind_rules_feedback: "每次猜测都会得到一排提示钉：图形和位置都正确会得到一个黑色提示钉，图形正确但位置错误则得到一个白色提示钉。例如，如果代码是圆形-圆形-方形-三角形，而你猜的是圆形-方形-方形-方形，你会得到两个黑色提示钉（第一个圆形和第三个方形完全正确），没有白色提示钉——因为猜测中多出来的方形在代码里已经没有可以对应的了。提示钉从不说明它们对应哪个格子，弄清楚这一点正是这个游戏的乐趣所在。",
    mastermind_rules_end_title: "结束一局游戏",
    mastermind_term_win: "获胜",
    mastermind_rules_win: "当某次猜测获得四个黑色提示钉时，你就获胜了——也就是每个图形都恰好在正确的位置上。",
    mastermind_term_loss: "用完猜测次数",
    mastermind_rules_loss: "每个难度都允许固定次数的猜测。如果用完了所有次数仍未猜出代码，游戏就此结束，并会揭晓秘密代码。",
    mastermind_term_levels: "难度等级",
    mastermind_rules_levels: "简单难度给你12次猜测机会，但秘密代码中不会出现重复图形。中等难度给10次猜测机会，并允许重复图形，这是这款游戏传统的玩法。困难难度只给8次猜测机会，同样允许重复图形，因此需要留意重复出现的图形。",

    mastermind_history_title: "Mastermind 的历史",
    mastermind_history_intro: "这是一款纯靠逻辑推理来破译密码的游戏，没有对手需要智取，它脱胎于一种历史更悠久的纸笔猜谜游戏，后来又成为计算机科学家研究如何高效搜索隐藏答案时喜爱探讨的课题。",
    mastermind_history_origins_title: "从 Bulls and Cows 到棋盘游戏",
    mastermind_history_origins_p1: "Mastermind 的核心机制——猜一个隐藏代码，得到的反馈只是完全匹配和部分匹配的数量，从不会告诉你哪些位置是对的——源自 Bulls and Cows，一种历史更悠久的纸笔（后来也有电脑版）猜谜游戏，传统上使用的是秘密数字，而不是图形或颜色。",
    mastermind_history_origins_p2: "1970年，以色列邮政局长兼电信专家 Mordecai Meirowitz 把这个想法改编成了一款使用彩色提示钉的实体棋盘游戏。这个创意先后被几家大型玩具公司拒绝，之后英国公司 Invicta Plastics 取得了授权，并于同一年以 Mastermind 之名将其推向市场。",
    mastermind_history_spread_title: "畅销之作",
    mastermind_history_spread_p1: "Invicta 出品的 Mastermind 成为20世纪70年代和80年代最畅销的游戏之一，最终在全球售出数千万套，并催生了旅行版、纯数字版本，以及一系列长期延续的续作和衍生作品。",
    mastermind_history_modern_title: "计算机科学家钟爱的谜题",
    mastermind_history_modern_p1: "由于这款游戏的本质，就是仅凭匹配数量的反馈去搜索一个隐藏答案，Mastermind 成为计算机科学和组合数学中研究猜测策略与搜索算法的经典范例，其影响远远超出了它作为一款聚会游戏的范畴。",
    mastermind_history_modern_p2: "在1977年一篇题为《The Computer as Master Mind》的著名论文中，Donald Knuth 证明了经典的四钉六图形版本，只要使用最优策略，总能在最多五次猜测内解出——这一结果至今仍常在讨论算法搜索时被引用。",
    game_kakuro: "卡库罗",
    home_kakuro_desc: "在白色格子中填入1到9的数字，使每个数字条的总和恰好等于其提示数，且同一数字条内不能重复数字。每次都会重新生成谜题，共有三个难度等级。",

